    ,COALESCE(IF(content_mix_frame_tab_name = '', NULL, content_mix_frame_tab_name), 'NA') AS content_mix_frame_tab_name
    ,COALESCE(IF(position_current_page = '', NULL, position_current_page), 'NA') AS current_page
