CREATE TEMPORARY VIEW dws_imp_click_${grass_region_without_quote} AS
SELECT
    IF(platform IS NOT NULL, platform, '__ALL__') AS platform
    ,IF(search_entrance IS NOT NULL, search_entrance, '__ALL__') AS search_entrance
    ,union_page_type AS page_type
    ,feature
    ,SUM(IF(operation = 'impression', operation_cnt, 0)) AS imp_cnt
    ,COUNT(DISTINCT IF(operation = 'impression', user_id, NULL)) AS imp_uu
    ,COUNT(DISTINCT IF(operation = 'impression', civ_id, NULL)) AS imp_feature_cnt
    ,SUM(IF(operation = 'click', operation_cnt, 0)) AS click_cnt
    ,COUNT(DISTINCT IF(operation = 'click', user_id, NULL)) AS click_uu
    ,SUM(IF(operation = 'order', operation_cnt, 0)) AS order_cnt
    ,COUNT(DISTINCT (IF(operation = 'order' AND operation_cnt  > 0, user_id, NULL))) AS order_uu
    ,SUM(IF(operation = 'order', gmv, 0)) AS gmv
    ,SUM(IF(operation = 'order', pc2_gmv, 0)) AS pc2_gmv
FROM
    dwd_search_with_feature_${grass_region_without_quote}
    lateral view explode(feature_tag) AS feature
WHERE
    operation in ('impression', 'click', 'order')
GROUP BY GROUPING SETS
(
    (union_page_type, feature) ,(platform, union_page_type, feature),
    (search_entrance, union_page_type, feature) ,(platform, search_entrance, union_page_type, feature)
);
