CREATE TEMPORARY VIEW omni_search_order_${grass_region_without_quote} AS
SELECT
    user_id
    ,COALESCE(platform, 'NA') AS platform
    ,COALESCE(IF(click_search_property.search_entrance = '', NULL, click_search_property.search_entrance), 'NA') AS search_entrance
    ,COALESCE(IF(click_search_property.search_mid = '', NULL, click_search_property.search_mid), 'NA') AS search_mid
    ,click_target_type AS target_type
    ,click_mapped_page_type AS mapped_page_type
    ,click_page_section AS page_section
    ,NULL AS input_type
    ,module
    ,SUM(order_fraction * atc_prorate * first_touchpoint_item) AS global_search_order_cnt
    ,SUM(gmv_usd * atc_prorate * first_touchpoint_item) AS global_search_gmv
    ,SUM(pc2_usd* atc_prorate * first_touchpoint_item) AS global_search_pc2
FROM
    traffic_omni_oa.dwd_order_item_atc_journey_di__reg_sensitive_live
WHERE
    grass_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND user_id > 0 AND user_id IS NOT NULL
GROUP BY 1,2,3,4,5,6,7,8,9
UNION ALL
SELECT
    user_id
    ,COALESCE(platform, 'NA') AS platform
    ,COALESCE(IF(source1_search_property.search_entrance = '', NULL, source1_search_property.search_entrance), 'NA') AS search_entrance
    ,COALESCE(IF(source1_search_property.search_mid = '', NULL, source1_search_property.search_mid), 'NA') AS search_mid
    ,source1_target_type AS target_type
    ,source1_mapped_page_type AS mapped_page_type
    ,source1_page_section AS page_section
    ,source1_search_property.input_type AS input_type
    ,source1_module AS module
    ,SUM(order_fraction * atc_prorate * first_touchpoint_item) AS global_search_order_cnt
    ,SUM(gmv_usd * atc_prorate * first_touchpoint_item) AS global_search_gmv
    ,SUM(pc2_usd* atc_prorate * first_touchpoint_item) AS global_search_pc2
FROM
    traffic_omni_oa.dwd_order_item_atc_journey_di__reg_sensitive_live
WHERE
    grass_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND user_id > 0 AND user_id IS NOT NULL
GROUP BY 1,2,3,4,5,6,7,8,9
UNION ALL
SELECT
    user_id
    ,COALESCE(platform, 'NA') AS platform
    ,COALESCE(IF(source2_search_property.search_entrance = '', NULL, source2_search_property.search_entrance), 'NA') AS search_entrance
    ,COALESCE(IF(source2_search_property.search_mid = '', NULL, source2_search_property.search_mid), 'NA') AS search_mid
    ,source2_target_type AS target_type
    ,source2_mapped_page_type AS mapped_page_type
    ,source2_page_section AS page_section
    ,source2_search_property.input_type AS input_type
    ,source2_module AS module
    ,SUM(order_fraction * atc_prorate * first_touchpoint_item) AS global_search_order_cnt
    ,SUM(gmv_usd * atc_prorate * first_touchpoint_item) AS global_search_gmv
    ,SUM(pc2_usd* atc_prorate * first_touchpoint_item) AS global_search_pc2
FROM
    traffic_omni_oa.dwd_order_item_atc_journey_di__reg_sensitive_live
WHERE
