CREATE TEMPORARY VIEW omni_search_order_with_feature_${grass_region_without_quote} AS
SELECT
    *
    ,CASE 
        WHEN search_mid IN ('sdp_algo_prefill','sdp_ops_prefill','sdp_default_prefill','sdp_prefill') AND module = 'Global Search' THEN array('srp-sdp-search_prefill')
        WHEN search_mid IN ('sdp_history','sdp_hint_history') AND module = 'Global Search' THEN array('srp-sdp-history_hint') 
        WHEN search_mid IN ('sdp_search_suggestion','sdp_trend_search') AND module = 'Global Search' AND platform in ('ios_app','android_app') THEN array('srp-sdp-search_suggestions')    
        WHEN search_mid IN ('sdp_hot_search') AND module = 'Global Search' THEN array('srp-sdp-hot_searches')
        WHEN search_mid IN ('sup_hint_history','sup_history') AND module = 'Global Search' THEN array('srp-sup-history_hint')
        WHEN search_mid IN ('sup_auto_complete','sup_query_suggest') AND module = 'Global Search' THEN array('srp-sup-auto_complete')
        WHEN search_mid IN ('sup_ymws') AND module = 'Global Search' THEN array('srp-sup-next_keyword')
        WHEN search_mid IN ('manual_input') AND module = 'Global Search' THEN array('srp-sup-manual_input')
        ELSE NULL
    END AS feature_tag
FROM 
    omni_search_order_${grass_region_without_quote}
UNION ALL 
SELECT
    *
    ,CASE 
        WHEN target_type = 'hint_keyword' AND mapped_page_type in ('pre_search')
            AND input_type = 'creator' THEN array('srp-sdp-creator_hint') 
        WHEN mapped_page_type = 'pre_search' AND page_section = 'search_bar'
            AND target_type = 'item_sharing_code' THEN array('srp-sdp-item_sharing_code' ) 
        WHEN target_type = 'hint_keyword' AND mapped_page_type in ('search_suggest_page')
            AND input_type = 'creator' THEN array('srp-sup-creator_hint')
        WHEN target_type = 'creator_livestream' AND page_section IS NULL
            AND mapped_page_type = 'search_suggest_page' THEN array('srp-sup-creator_livestream')
        WHEN target_type = 'hint_keyword' AND page_section IS NULL
            AND mapped_page_type = 'search_creator_page' THEN array('srp-search_creator_page-creator_hint')
        WHEN target_type = 'creator_livestream' AND page_section IS NULL
            AND mapped_page_type = 'search_creator_page' THEN array('srp-search_creator_page-creator_livestream')
        ELSE NULL
    END AS feature_tag
FROM 
    omni_search_order_${grass_region_without_quote}
UNION ALL
SELECT
    *
    ,CASE 
        WHEN search_entrance IN ('homepage_search_bar') AND module = 'Global Search' THEN array('srp-home-search_bar', 'srp-all-main_search')
        WHEN search_entrance IN ('homepage_dd_card') AND module = 'Global Search' THEN array('srp-home-dd_search_card')
        WHEN search_entrance IN ('pdp_search_bar') AND module = 'Global Search' THEN array('srp-pdp-search_bar', 'srp-all-main_search')
        WHEN search_entrance IN ('pdp_ymal_card') AND module = 'Global Search' THEN array('srp-pdp-ymal_search_card')
        WHEN search_entrance IN ('mpp_ymal_card') AND module = 'Global Search' THEN array('srp-order_list-ymal_search_card')
        WHEN search_entrance IN ('osp_ymal_card') AND module = 'Global Search' THEN array('srp-order_successful-ymal_search_card')
        WHEN search_entrance IN ('cart_ymal_card') AND module = 'Global Search' THEN array('srp-shopping_cart-ymal_search_card')
        WHEN search_entrance IN ('srp_search_bar') AND module = 'Global Search' THEN array('srp-srp-search_bar')
        WHEN search_entrance IN ('srp_related_search') AND module = 'Global Search' THEN array('srp-srp-related_search')
        WHEN search_entrance IN ('video_search') AND module = 'Global Search' THEN array('srp-video-video_search', 'srp-all-all_content_search')
        WHEN search_entrance IN ('content_mix_search') AND module = 'Global Search' THEN array('srp-content_mix_frame-content_mix_search', 'srp-all-all_content_search')
        WHEN search_entrance IN ('live_search') AND module = 'Global Search' THEN array('srp-live-live_search', 'srp-all-all_content_search')
        ELSE NULL
    END AS feature_tag
FROM 
    omni_search_order_${grass_region_without_quote};

