CREATE TEMPORARY VIEW dws_omni_search_${grass_region_without_quote} AS
SELECT 
    feature
    ,'search' AS page_type
    ,IF(platform IS NOT NULL, platform, '__ALL__') AS platform
    ,IF(search_entrance IS NOT NULL, search_entrance, '__ALL__') AS search_entrance
    ,SUM(global_search_order_cnt) AS global_search_order_cnt
    ,COUNT(DISTINCT (IF(global_search_order_cnt > 0 , user_id, NULL))) AS global_search_order_uu
    ,SUM(global_search_gmv) AS global_search_gmv
    ,SUM(global_search_pc2) AS global_search_pc2
FROM 
    omni_search_order_with_feature_${grass_region_without_quote}
    lateral view explode(feature_tag) AS feature
GROUP BY GROUPING SETS
(
    (feature) ,(platform, feature),
    (search_entrance, feature) ,(platform, search_entrance, feature)
); 

