CREATE TEMPORARY VIEW search_guide_${grass_region_without_quote} AS
SELECT 
    union_page_type
    ,feature
    ,COALESCE(platform, 'NA') AS platform
    ,COALESCE(IF(search_entrance = '', NULL, search_entrance), 'NA') AS search_entrance
    ,user_id
    ,trim(lower(keyword)) AS keyword
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
FROM
    srdi_mart.dws_sr_data_warehouse_search_guide_user_benchmark_1d
    lateral view explode(feature_tag) AS feature
WHERE 
    local_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND keyword IS NOT NULL
    AND user_id > 0
    AND (
        imp_cnt > 0 
        OR click_cnt > 0
    )
GROUP BY
    1,2,3,4,5,6;

