CREATE TEMPORARY VIEW search_guide_with_l3_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(platform IS NOT NULL, platform, '__ALL__') AS platform
    ,IF(search_entrance IS NOT NULL, search_entrance, '__ALL__') AS search_entrance
    ,union_page_type AS page_type
    ,feature
    ,COUNT(DISTINCT IF(imp_cnt > 0, level3_keyword_category_id, NULL)) AS imp_l3_cnt
    ,COUNT(DISTINCT IF(click_cnt > 0, level3_keyword_category_id, NULL)) AS clk_l3_cnt
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
FROM 
   search_guide_${grass_region_without_quote} a
   INNER JOIN  dim_keyword_l3_${grass_region_without_quote} b 
   ON a.keyword = b.keyword 
GROUP BY GROUPING SETS
(
    (user_id, union_page_type, feature) ,(user_id, platform, union_page_type, feature),
    (user_id, search_entrance, union_page_type, feature) ,(user_id, platform, search_entrance, union_page_type, feature)
);

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_keyword_l3_${grass_region_without_quote} AS
SELECT
    platform
    ,search_entrance
    ,page_type
    ,feature
    ,SUM(imp_l3_cnt) / COUNT(IF(imp_cnt > 0, 1, NULL)) AS imp_l3_cat_per_uu
    ,SUM(clk_l3_cnt) / COUNT(IF(click_cnt > 0, 1, NULL)) AS clk_l3_cat_per_uu
FROM
    search_guide_with_l3_${grass_region_without_quote}
GROUP BY 
    1,2,3,4;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_guide_performance_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    coalesce(dws_imp_click.platform, dws_view.platform, dws_omni_search.platform) AS platform
    ,coalesce(dws_imp_click.search_entrance, dws_view.search_entrance, dws_omni_search.search_entrance) AS search_entrance
    ,coalesce(dws_imp_click.page_type, dws_view.page_type, dws_omni_search.page_type) AS page_type
    ,coalesce(dws_imp_click.feature, dws_view.feature, dws_omni_search.feature) AS feature
    ,imp_cnt
    ,imp_uu
    ,imp_feature_cnt
    ,click_cnt
    ,click_uu
    ,page_view_cnt
    ,page_view_uu
    ,order_cnt
    ,order_uu
    ,gmv
    ,pc2_gmv
    ,IF(split(dws_view.feature, '-')[0] IN ('sdp','sup','srp'), search_volume, NULL) search_volume
    ,global_search_order_cnt
    ,global_search_order_uu
    ,global_search_gmv
    ,global_search_pc2
    ,content_scenario_dau
    ,imp_l3_cat_per_uu
    ,clk_l3_cat_per_uu
FROM
    dws_imp_click_${grass_region_without_quote} dws_imp_click
    LEFT JOIN dws_content_user_${grass_region_without_quote} dws_content_user
    ON dws_imp_click.platform = '__ALL__'
        AND dws_imp_click.search_entrance = '__ALL__'
        AND dws_imp_click.page_type = dws_content_user.page_type
        AND dws_imp_click.feature = dws_content_user.feature
    LEFT JOIN dws_keyword_l3_${grass_region_without_quote} dws_keyword_l3
    ON dws_imp_click.platform = dws_keyword_l3.platform
        AND dws_imp_click.search_entrance = dws_keyword_l3.search_entrance
        AND dws_imp_click.page_type = dws_keyword_l3.page_type
        AND dws_imp_click.feature = dws_keyword_l3.feature
    FULL OUTER JOIN dws_view_${grass_region_without_quote} dws_view
    ON dws_imp_click.platform = dws_view.platform
        AND dws_imp_click.search_entrance = dws_view.search_entrance
        AND dws_imp_click.page_type = dws_view.page_type
        AND dws_imp_click.feature = dws_view.feature
    FULL OUTER JOIN dws_omni_search_${grass_region_without_quote} dws_omni_search
    ON dws_imp_click.platform = dws_omni_search.platform
        AND dws_imp_click.search_entrance = dws_omni_search.search_entrance
        AND dws_imp_click.page_type = dws_omni_search.page_type
        AND dws_imp_click.feature = dws_omni_search.feature;
